var N = 8, T = 14;
function mk(a) { return function () { a |= 0; a = a + 0x6D2B79F5 | 0; var t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
var rnd = mk(7);
function c01(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
function ease(x) { x = c01(x); return x * x * (3 - 2 * x); }
function rgba(a) { return 'rgba(11,79,192,' + c01(a).toFixed(3) + ')'; }
var Q = [], K = [], V = [], A = [], O = [];
for (var i = 0; i < N; i++) {
  var q = [], k = [], v = [];
  for (var d = 0; d < 4; d++) { q.push((rnd() * 2 - 1) * 1.2); k.push((rnd() * 2 - 1) * 1.2); v.push(0.25 + rnd() * 0.75); }
  Q.push(q); K.push(k); V.push(v);
}
for (var i2 = 0; i2 < N; i2++) {
  var sc = [], mx = -1e9, sm = 0;
  for (var j = 0; j < N; j++) {
    var dot = 0;
    for (var d2 = 0; d2 < 4; d2++) dot += Q[i2][d2] * K[j][d2];
    sc.push(dot / 2 * 3.5); if (sc[j] > mx) mx = sc[j];
  }
  for (var j2 = 0; j2 < N; j2++) { sc[j2] = Math.exp(sc[j2] - mx); sm += sc[j2]; }
  var row = [], o = [0, 0, 0, 0];
  for (var j3 = 0; j3 < N; j3++) { row.push(sc[j3] / sm); for (var d3 = 0; d3 < 4; d3++) o[d3] += row[j3] * V[j3][d3]; }
  A.push(row); O.push(o);
}
var qs = [2, 5, 0, 7];
var vcol = ['#0B4FC0', '#B4552F', '#138374', '#6A47C2'];
var revs = [[2, 3.0, 1.0], [5, 8.2, 0.7], [0, 9.6, 0.7], [7, 11.0, 0.6]];
var capt = ['1 · softmax(q·k/√d) gives each key a weight', '2 · Values flow along the arrows and add up', '3 · Next queries get different weights', 'Cost grows with the number of tokens squared'];
var starts = [0, 4.2, 7.4, 11.6];

function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, width, height);
  var t = time % T;
  var wide = width >= 620;
  var x0, x1, pitch, s, tokY, vh, outBase, obH, peakCap, rx, rw, hc, hx, hy, bx, by, bww, bhh, tY, lblY;
  if (wide) {
    x0 = 18; x1 = Math.min(width * 0.6, width - 250); pitch = (x1 - x0) / 8; s = Math.min(44, pitch * 0.72);
    tokY = 140; vh = 24; outBase = 300; obH = 40; peakCap = 70;
    rx = x1 + 26; rw = Math.min(300, width - 16 - rx); hc = Math.min(18, rw / 8);
    hx = rx + (rw - 8 * hc) / 2; hy = 206;
    bx = rx; bww = rw; bhh = 58; by = 140; tY = 54; lblY = 155;
  } else {
    x0 = 14; x1 = width - 14; pitch = (x1 - x0) / 8; s = Math.min(40, pitch * 0.72);
    tokY = 92; vh = 20; outBase = 226; obH = 30; peakCap = 44;
    bx = 14; bww = width / 2 - 24; bhh = 58; by = 366; tY = 292; lblY = 380;
    hc = 9; hx = width * 0.75 - 36; hy = 300; rx = 0; rw = 0;
  }
  var valY = tokY + s + 6;
  function tx(j) { return x0 + pitch * (j + 0.5); }

  var from = qs[0], to = qs[0], m = 0;
  if (t >= 7.4 && t < 11.6) {
    var k = Math.min(2, Math.floor((t - 7.4) / 1.4));
    var loc = (t - 7.4 - k * 1.4) / 1.4;
    from = qs[k]; to = qs[k + 1]; m = ease(loc / 0.55);
  } else if (t >= 11.6) { from = to = qs[3]; }
  var qx = tx(from) * (1 - m) + tx(to) * m;
  var w = [];
  for (var j = 0; j < N; j++) w.push(A[from][j] * (1 - m) + A[to][j] * m);
  var grow = t < 4.2 ? ease((t - 0.5) / 1.8) : 1;
  var am;
  if (t < 4.2) am = 1;
  else if (t < 4.7) am = 1 - 0.7 * ease((t - 4.2) / 0.5);
  else if (t < 7.0) am = 0.3;
  else if (t < 7.6) am = 0.3 + 0.7 * ease((t - 7.0) / 0.6);
  else if (t < 11.6) am = 1;
  else am = 1 - 0.85 * ease((t - 11.6) / 0.6);
  var ph = t < 4.2 ? 0 : t < 7.4 ? 1 : t < 11.6 ? 2 : 3;
  var qd = m > 0.5 ? to : from;

  ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
  var fs = 13; ctx.font = 'bold ' + fs + 'px sans-serif';
  while (fs > 11 && ctx.measureText(capt[ph]).width > width - 16) { fs--; ctx.font = 'bold ' + fs + 'px sans-serif'; }
  ctx.globalAlpha = c01((t - starts[ph]) / 0.3 + (ph === 0 ? 1 : 0));
  ctx.fillStyle = '#04204B'; ctx.fillText(capt[ph], width / 2, 22);
  ctx.globalAlpha = 1;
  ctx.font = '12px sans-serif'; ctx.fillStyle = '#3D5F91';
  ctx.fillText('query = x' + (qd + 1) + ', reads all ' + N + ' tokens', width / 2, 40);

  ctx.textAlign = 'center';
  for (var j1 = 0; j1 < N; j1++) {
    var cx = tx(j1), X = cx - s / 2;
    ctx.fillStyle = '#F3F6FB'; ctx.fillRect(X, tokY, s, s);
    var ov = Math.min(0.5, w[j1] * 1.2) * grow * (0.4 + 0.6 * am);
    ctx.fillStyle = rgba(ov); ctx.fillRect(X, tokY, s, s);
    ctx.strokeStyle = '#C3D1E8'; ctx.lineWidth = 1; ctx.beginPath();
    ctx.moveTo(X + s * 0.12, tokY + s * (0.8 - 0.1 * (j1 % 3)));
    ctx.lineTo(X + s * 0.45, tokY + s * 0.42);
    ctx.lineTo(X + s * 0.88, tokY + s * (0.75 - 0.1 * ((j1 + 1) % 3)));
    ctx.stroke();
    ctx.beginPath(); ctx.arc(X + s * 0.74, tokY + s * 0.26, s * 0.07, 0, 6.2832); ctx.stroke();
    ctx.strokeStyle = '#8098BC'; ctx.strokeRect(X, tokY, s, s);
    var isQ = (j1 === from ? 1 - m : 0) + (j1 === to ? m : 0);
    if (isQ > 0.01) { ctx.strokeStyle = rgba(isQ); ctx.lineWidth = 3; ctx.strokeRect(X - 1, tokY - 1, s + 2, s + 2); }
    ctx.fillStyle = '#04204B'; ctx.font = '11px sans-serif';
    ctx.fillText('x' + (j1 + 1), cx, tokY + s / 2 + 4);
    var bw = s / 6, gp = bw * 0.3, vx = cx - (4 * bw + 3 * gp) / 2;
    for (var d = 0; d < 4; d++) {
      ctx.fillStyle = vcol[d]; var hh = V[j1][d] * vh;
      ctx.fillRect(vx + d * (bw + gp), valY + vh - hh, bw, hh);
    }
  }

  function head(x, y, dx, dy, sz) {
    var L = Math.sqrt(dx * dx + dy * dy) || 1; dx /= L; dy /= L;
    ctx.beginPath(); ctx.moveTo(x, y);
    ctx.lineTo(x - dx * sz - dy * sz * 0.5, y - dy * sz + dx * sz * 0.5);
    ctx.lineTo(x - dx * sz + dy * sz * 0.5, y - dy * sz - dx * sz * 0.5);
    ctx.closePath(); ctx.fill();
  }
  var g = grow;
  if (g > 0.01) {
    for (var j2 = 0; j2 < N; j2++) {
      var kx = tx(j2), dx = kx - qx, wj = w[j2];
      var al = am * c01(0.18 + wj * 2.2);
      ctx.strokeStyle = rgba(al); ctx.fillStyle = rgba(al); ctx.lineWidth = 0.8 + wj * 9;
      if (Math.abs(dx) < 0.25 * pitch) {
        var r = pitch * 0.2;
        ctx.beginPath(); ctx.arc(kx, tokY - r - 2, r, 1.5708, 1.5708 + 6.2832 * g); ctx.stroke();
      } else {
        var pk = Math.min(peakCap, 12 + Math.abs(dx) * 0.22);
        var cx0 = qx, cy0 = tokY - 1, ccx = (qx + kx) / 2, ccy = tokY - 2 * pk, ex = kx, ey = tokY - 1;
        var px = cx0, py = cy0, lx = cx0, ly = cy0;
        ctx.beginPath(); ctx.moveTo(cx0, cy0);
        for (var n = 1; n <= 14; n++) {
          var u = g * n / 14, a1 = (1 - u) * (1 - u), b1 = 2 * (1 - u) * u, c1 = u * u;
          lx = px; ly = py;
          px = a1 * cx0 + b1 * ccx + c1 * ex; py = a1 * cy0 + b1 * ccy + c1 * ey;
          ctx.lineTo(px, py);
        }
        ctx.stroke();
        head(px, py, px - lx, py - ly, 4 + wj * 8);
      }
    }
  }

  var bcx = Math.max(34, Math.min(width - 34, qx));
  var sy = valY + vh + 2, ey2 = outBase - obH - 4;
  var pf = ease((t - 4.2) / 0.4) * (1 - ease((t - 7.0) / 0.4));
  var outV = [0, 0, 0, 0];
  var inB = t >= 4.2 && t < 7.4, u2 = (t - 4.2) / 3.2;
  if (inB) {
    for (var j3 = 0; j3 < N; j3++) {
      var kx3 = tx(j3), wj3 = A[qs[0]][j3];
      var p = ease((u2 - j3 * 0.06) / 0.55);
      ctx.strokeStyle = rgba(0.15 * pf); ctx.lineWidth = 0.6 + wj3 * 6;
      ctx.beginPath(); ctx.moveTo(kx3, sy); ctx.quadraticCurveTo(kx3, ey2, bcx, ey2); ctx.stroke();
      for (var d4 = 0; d4 < 4; d4++) outV[d4] += wj3 * V[j3][d4] * p;
      if (p > 0 && p < 1) {
        var a2 = (1 - p) * (1 - p), b2 = 2 * (1 - p) * p, c2 = p * p;
        var gx = a2 * kx3 + b2 * kx3 + c2 * bcx, gy = a2 * sy + b2 * ey2 + c2 * ey2;
        var scl = c01(0.4 + wj3 * 1.8), gw = Math.max(2, s / 8 * scl);
        ctx.globalAlpha = p > 0.92 ? (1 - p) / 0.08 : 1;
        for (var d5 = 0; d5 < 4; d5++) {
          ctx.fillStyle = vcol[d5]; var gh = V[j3][d5] * 16 * scl;
          ctx.fillRect(gx + (d5 - 2) * (gw + 1), gy - gh, gw, gh);
        }
        ctx.globalAlpha = 1;
      }
    }
  } else if (t >= 7.4) {
    for (var d6 = 0; d6 < 4; d6++) outV[d6] = O[from][d6] * (1 - m) + O[to][d6] * m;
  }

  var oa = ease((t - 3.8) / 0.4) * (1 - ease((t - 13.5) / 0.5));
  if (oa > 0.01) {
    ctx.globalAlpha = oa;
    var obw = Math.max(6, s * 0.28), og = 3, ow = 4 * obw + 3 * og;
    ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 1;
    ctx.strokeRect(bcx - ow / 2 - 4, outBase - obH - 4, ow + 8, obH + 8);
    for (var d7 = 0; d7 < 4; d7++) {
      ctx.fillStyle = vcol[d7]; var oh = outV[d7] * obH;
      ctx.fillRect(bcx - ow / 2 + d7 * (obw + og), outBase - oh, obw, oh);
    }
    ctx.fillStyle = '#04204B'; ctx.font = '12px sans-serif'; ctx.textAlign = 'center';
    var lx2 = Math.max(70, Math.min(width - 70, bcx));
    ctx.fillText("x" + (qd + 1) + "' = Σ wⱼ vⱼ", lx2, outBase + 24);
    ctx.globalAlpha = 1;
  }
  ctx.textAlign = 'left'; ctx.font = '11px sans-serif'; ctx.fillStyle = '#3D5F91';
  ctx.fillText('bars under tokens = value vectors v', wide ? 18 : 14, wide ? 386 : outBase + 46);

  var sum = 0;
  for (var j4 = 0; j4 < N; j4++) sum += w[j4] * grow;
  ctx.textAlign = 'left'; ctx.font = '12px sans-serif'; ctx.fillStyle = '#04204B';
  ctx.fillText('weights w, Σ = ' + sum.toFixed(2), bx, tY);
  if (wide) { ctx.fillStyle = '#3D5F91'; ctx.fillText('softmax(q·k/√d) over the keys', bx, tY + 16); }
  var barW = bww / 8;
  ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(bx, by + 0.5); ctx.lineTo(bx + bww, by + 0.5); ctx.stroke();
  ctx.textAlign = 'center'; ctx.font = '11px sans-serif';
  for (var j5 = 0; j5 < N; j5++) {
    var bh2 = c01(w[j5] * grow / 0.5) * bhh;
    ctx.fillStyle = rgba(0.35 + 0.65 * c01(w[j5] / 0.4));
    ctx.fillRect(bx + j5 * barW + barW * 0.15, by - bh2, barW * 0.7, bh2);
    ctx.fillStyle = '#3D5F91';
    ctx.fillText('' + (j5 + 1), bx + j5 * barW + barW / 2, lblY);
  }

  var hf = 1 - ease((t - 13.5) / 0.5);
  var rp = [];
  for (var r0 = 0; r0 < N; r0++) rp.push(0);
  for (var e = 0; e < revs.length; e++) rp[revs[e][0]] = ease((t - revs[e][1]) / revs[e][2]);
  var cnt = 0;
  for (var r1 = 0; r1 < N; r1++) {
    if (qs.indexOf(r1) < 0) { rp[r1] = ease((t - (11.8 + cnt * 0.35)) / 0.5); cnt++; }
  }
  ctx.textAlign = 'left'; ctx.font = '12px sans-serif'; ctx.fillStyle = '#04204B';
  ctx.fillText(wide ? 'weight matrix A (N×N, N = 8)' : 'A (N×N)', hx, wide ? hy - 10 : tY);
  ctx.fillStyle = '#F3F6FB'; ctx.fillRect(hx, hy, 8 * hc, 8 * hc);
  ctx.globalAlpha = hf;
  for (var ri = 0; ri < N; ri++) {
    if (rp[ri] <= 0) continue;
    for (var cj = 0; cj < N; cj++) {
      var ca = c01(rp[ri] * 1.6 - cj * 0.075) * c01(A[ri][cj] / 0.45) * 0.95;
      if (ca > 0.01) { ctx.fillStyle = rgba(ca); ctx.fillRect(hx + cj * hc, hy + ri * hc, hc, hc); }
    }
  }
  ctx.globalAlpha = 1;
  ctx.strokeStyle = '#C3D1E8'; ctx.lineWidth = 0.5; ctx.beginPath();
  for (var gi = 1; gi < N; gi++) {
    ctx.moveTo(hx + gi * hc, hy); ctx.lineTo(hx + gi * hc, hy + 8 * hc);
    ctx.moveTo(hx, hy + gi * hc); ctx.lineTo(hx + 8 * hc, hy + gi * hc);
  }
  ctx.stroke();
  ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 1; ctx.strokeRect(hx, hy, 8 * hc, 8 * hc);
  if (t < 11.6) {
    ctx.lineWidth = 2;
    ctx.strokeStyle = rgba(1 - m); ctx.strokeRect(hx - 1, hy + from * hc - 1, 8 * hc + 2, hc + 2);
    ctx.strokeStyle = rgba(m); ctx.strokeRect(hx - 1, hy + to * hc - 1, 8 * hc + 2, hc + 2);
  }
  var dA = ease((t - 11.6) / 0.5) * hf;
  ctx.textAlign = 'left'; ctx.font = '12px sans-serif';
  var ty2 = hy + 8 * hc + 16;
  ctx.globalAlpha = 1 - dA; ctx.fillStyle = '#3D5F91';
  ctx.fillText(wide ? 'rows i = queries, cols j = keys' : 'rows i, cols j', hx, ty2);
  ctx.globalAlpha = dA; ctx.fillStyle = '#B4552F';
  ctx.fillText(wide ? 'N² = 64 weights to compute' : 'N² = 64 weights', hx, ty2);
  ctx.globalAlpha = 1;
}
return { draw: draw };
